-- AS Code Assess initial schema. Apply with Supabase CLI or SQL editor.
create extension if not exists pgcrypto;
create type public.app_role as enum ('ADMIN','STUDENT');
create type public.test_status as enum ('DRAFT','READY','PUBLISHED','CLOSED');
create type public.question_type as enum ('MCQ','THEORY');
create type public.assignment_status as enum ('ASSIGNED','IN_PROGRESS','COMPLETED','EXPIRED');
create type public.attempt_status as enum ('IN_PROGRESS','SUBMITTED','AUTO_SUBMITTED','ABANDONED');
create type public.recording_status as enum ('ACTIVE','COMPLETED','FAILED');
create type public.result_visibility as enum ('IMMEDIATE','AFTER_REVIEW','NEVER');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text not null, full_name text, role public.app_role not null default 'STUDENT', is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tests (id uuid primary key default gen_random_uuid(), title text not null, description text, instructions text, duration_minutes integer not null check (duration_minutes between 1 and 600), passing_score numeric(5,2) not null default 50 check (passing_score between 0 and 100), status public.test_status not null default 'DRAFT', starts_at timestamptz, ends_at timestamptz, result_visibility public.result_visibility not null default 'AFTER_REVIEW', created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.questions (id uuid primary key default gen_random_uuid(), test_id uuid not null references public.tests(id) on delete cascade, order_index integer not null, type public.question_type not null, prompt text not null, points numeric(8,2) not null check (points > 0), correct_option_id uuid, is_published boolean not null default false, needs_review boolean not null default false, created_at timestamptz not null default now(), unique(test_id,order_index));
create table public.question_options (id uuid primary key default gen_random_uuid(), question_id uuid not null references public.questions(id) on delete cascade, option_key char(1) not null check(option_key in ('A','B','C','D')), label text not null, unique(question_id,option_key));
alter table public.questions add constraint questions_correct_option_fk foreign key(correct_option_id) references public.question_options(id);
create table public.test_assignments (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles(id) on delete cascade, test_id uuid not null references public.tests(id) on delete cascade, assigned_at timestamptz not null default now(), due_at timestamptz, status public.assignment_status not null default 'ASSIGNED', unique(student_id,test_id));
create table public.attempts (id uuid primary key default gen_random_uuid(), assignment_id uuid not null references public.test_assignments(id), student_id uuid not null references public.profiles(id), test_id uuid not null references public.tests(id), status public.attempt_status not null default 'IN_PROGRESS', started_at timestamptz not null default now(), expires_at timestamptz not null, submitted_at timestamptz, score numeric(10,2), total_points numeric(10,2), locked_at timestamptz, automatic_submission boolean not null default false);
create table public.answers (id uuid primary key default gen_random_uuid(), attempt_id uuid not null references public.attempts(id) on delete cascade, question_id uuid not null references public.questions(id), selected_option_id uuid references public.question_options(id), answer_text text, awarded_points numeric(10,2), locked_at timestamptz not null default now(), created_at timestamptz not null default now(), unique(attempt_id,question_id));
create table public.recording_sessions (id uuid primary key default gen_random_uuid(), attempt_id uuid not null references public.attempts(id) on delete cascade, student_id uuid not null references public.profiles(id), status public.recording_status not null default 'ACTIVE', started_at timestamptz not null default now(), ended_at timestamptz, chunk_count integer not null default 0);
create table public.recording_chunks (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.recording_sessions(id) on delete cascade, chunk_number integer not null, storage_path text not null unique, byte_size bigint not null, uploaded_at timestamptz not null default now(), unique(session_id,chunk_number));
create table public.activity_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id), student_id uuid references public.profiles(id), attempt_id uuid references public.attempts(id), event_type text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table public.test_reviews (id uuid primary key default gen_random_uuid(), attempt_id uuid not null references public.attempts(id) on delete cascade, question_id uuid not null references public.questions(id), reviewer_id uuid not null references public.profiles(id), awarded_points numeric(10,2) not null check(awarded_points>=0), comment text, reviewed_at timestamptz not null default now(), unique(attempt_id,question_id));
create table public.settings (key text primary key, value jsonb not null, updated_by uuid references public.profiles(id), updated_at timestamptz not null default now());

create index idx_assignments_student on public.test_assignments(student_id,status); create index idx_attempts_student on public.attempts(student_id,status); create index idx_attempts_test on public.attempts(test_id); create index idx_answers_attempt on public.answers(attempt_id); create index idx_recording_sessions_attempt on public.recording_sessions(attempt_id); create index idx_activity_attempt on public.activity_logs(attempt_id,created_at desc);

create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='ADMIN' and is_active); $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,full_name) values(new.id,new.email,new.raw_user_meta_data->>'full_name') on conflict(id) do update set email=excluded.email; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

create or replace function public.start_attempt(p_assignment_id uuid) returns public.attempts language plpgsql security definer set search_path=public as $$ declare a public.attempts; ass public.test_assignments; t public.tests; begin select * into ass from public.test_assignments where id=p_assignment_id and student_id=auth.uid() for update; if ass.id is null then raise exception 'Assignment not found'; end if; select * into t from public.tests where id=ass.test_id and status='PUBLISHED'; if t.id is null then raise exception 'Assessment is not available'; end if; if t.starts_at is not null and now()<t.starts_at then raise exception 'Assessment has not started'; end if; if t.ends_at is not null and now()>t.ends_at then raise exception 'Assessment has expired'; end if; select * into a from public.attempts where assignment_id=ass.id and student_id=auth.uid() order by started_at desc limit 1; if a.id is not null then if a.status='IN_PROGRESS' and now()<a.expires_at then return a; else raise exception 'This assignment already has a submitted attempt'; end if; end if; insert into public.attempts(assignment_id,student_id,test_id,expires_at,total_points) select ass.id,auth.uid(),t.id,now()+(t.duration_minutes||' minutes')::interval,coalesce((select sum(points) from public.questions where test_id=t.id and is_published),0) returning * into a; update public.test_assignments set status='IN_PROGRESS' where id=ass.id; return a; end; $$;

create or replace function public.submit_answer(p_attempt_id uuid,p_question_id uuid,p_answer_text text,p_selected_option_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare a public.attempts; q public.questions; awarded numeric; begin select * into a from public.attempts where id=p_attempt_id and student_id=auth.uid() for update; if a.id is null then raise exception 'Attempt not found'; end if; if a.status<>'IN_PROGRESS' or now()>=a.expires_at then raise exception 'The assessment is no longer accepting answers'; end if; select * into q from public.questions where id=p_question_id and test_id=a.test_id and is_published; if q.id is null then raise exception 'Question not found'; end if; if exists(select 1 from public.answers where attempt_id=a.id and question_id=q.id) then raise exception 'This answer is locked'; end if; if q.type='MCQ' then if p_selected_option_id is null then raise exception 'Select an answer'; end if; awarded:=case when q.correct_option_id=p_selected_option_id then q.points else 0 end; else awarded:=null; end if; insert into public.answers(attempt_id,question_id,selected_option_id,answer_text,awarded_points) values(a.id,q.id,p_selected_option_id,p_answer_text,awarded); return jsonb_build_object('id',p_attempt_id,'question_id',p_question_id); end; $$;

create or replace function public.finalize_attempt(p_attempt_id uuid,p_automatic boolean default false) returns public.attempts language plpgsql security definer set search_path=public as $$ declare a public.attempts; begin select * into a from public.attempts where id=p_attempt_id and student_id=auth.uid() for update; if a.id is null then raise exception 'Attempt not found'; end if; if a.status<>'IN_PROGRESS' then return a; end if; update public.attempts set status=case when p_automatic then 'AUTO_SUBMITTED' else 'SUBMITTED' end, submitted_at=now(), locked_at=now(), automatic_submission=p_automatic, score=(select coalesce(sum(awarded_points),0) from public.answers where attempt_id=p_attempt_id) where id=p_attempt_id returning * into a; update public.test_assignments set status='COMPLETED' where id=a.assignment_id; return a; end; $$;

alter table public.profiles enable row level security; alter table public.tests enable row level security; alter table public.questions enable row level security; alter table public.question_options enable row level security; alter table public.test_assignments enable row level security; alter table public.attempts enable row level security; alter table public.answers enable row level security; alter table public.recording_sessions enable row level security; alter table public.recording_chunks enable row level security; alter table public.activity_logs enable row level security; alter table public.test_reviews enable row level security; alter table public.settings enable row level security;
create policy profiles_self_or_admin on public.profiles for select using(id=auth.uid() or public.is_admin()); create policy profiles_admin_write on public.profiles for all using(public.is_admin()) with check(public.is_admin());
create policy tests_published_for_students on public.tests for select using(status='PUBLISHED' and exists(select 1 from public.test_assignments a where a.test_id=id and a.student_id=auth.uid()) or public.is_admin()); create policy tests_admin_write on public.tests for all using(public.is_admin()) with check(public.is_admin());
create policy questions_published_for_students on public.questions for select using(is_published and exists(select 1 from public.test_assignments a where a.test_id=questions.test_id and a.student_id=auth.uid()) or public.is_admin()); create policy question_options_published_for_students on public.question_options for select using(exists(select 1 from public.questions q where q.id=question_id and q.is_published and exists(select 1 from public.test_assignments a where a.test_id=q.test_id and a.student_id=auth.uid())) or public.is_admin());
create policy assignments_self_or_admin on public.test_assignments for select using(student_id=auth.uid() or public.is_admin()); create policy assignments_admin_write on public.test_assignments for all using(public.is_admin()) with check(public.is_admin());
create policy attempts_self_or_admin on public.attempts for select using(student_id=auth.uid() or public.is_admin()); create policy answers_self_or_admin on public.answers for select using(exists(select 1 from public.attempts a where a.id=attempt_id and (a.student_id=auth.uid() or public.is_admin()))); create policy recording_self_or_admin on public.recording_sessions for select using(student_id=auth.uid() or public.is_admin()); create policy recording_student_insert on public.recording_sessions for insert to authenticated with check(student_id=auth.uid() and exists(select 1 from public.attempts a where a.id=attempt_id and a.student_id=auth.uid() and a.status='IN_PROGRESS')); create policy recording_student_update on public.recording_sessions for update to authenticated using(student_id=auth.uid()) with check(student_id=auth.uid()); create policy chunks_self_or_admin on public.recording_chunks for select using(exists(select 1 from public.recording_sessions s where s.id=session_id and (s.student_id=auth.uid() or public.is_admin()))); create policy activity_admin_or_self on public.activity_logs for select using(student_id=auth.uid() or public.is_admin()); create policy reviews_admin on public.test_reviews for all using(public.is_admin()) with check(public.is_admin()); create policy settings_admin on public.settings for all using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets(id,name,public) values('question-papers','question-papers',false),('recordings','recordings',false),('optional-assets','optional-assets',false) on conflict(id) do nothing;
create policy storage_admin_recordings on storage.objects for all using(bucket_id='recordings' and public.is_admin()) with check(bucket_id='recordings' and public.is_admin());
create policy storage_student_recordings_upload on storage.objects for insert to authenticated with check(bucket_id='recordings' and (storage.foldername(name))[4]=auth.uid()::text);
